"""plan.py - the addressing plan as a Markdown table (docs/ADDRESSING.md is generated by it)."""
import ipaddress


def plan(net):
    a = net.raw["addressing"]
    r1 = net.raw["routers"]["R1"]
    sw = net.raw["switches"]
    out = ["# Addressing plan", "", "Generated by `python -m campus plan` from network.yaml.", "",
           "## VLANs", "",
           "| VLAN | Name | IPv4 subnet | Gateway (HSRP) | D1 | D2 | DHCP pool | IPv6 /64 | Active / STP root |",
           "| ---: | --- | --- | --- | --- | --- | --- | --- | --- |"]
    for v in sorted(net.vlans.values(), key=lambda v: v.id):
        if v.v4 is None:
            out.append(f"| {v.id} | {v.name} | - | - | - | - | - | - | unused ports, native VLAN of every trunk |")
            continue
        pool = (f"{v.host(a['dhcp_excluded_last'] + 1)} - {v.v4.broadcast_address - 1}" if v.dhcp else "static")
        out.append(f"| {v.id} | {v.name} | {v.v4} | {v.host(a['gateway_host'])} | {v.host(a['d1_host'])} | "
                   f"{v.host(a['d2_host'])} | {pool} | {v.v6} | {v.primary} |")
    out += ["", "## Point-to-point links and loopback", "", "| Link | Subnet | Addresses |", "| --- | --- | --- |"]
    for ifn, i in r1["interfaces"].items():
        n = ipaddress.ip_interface(i["v4"]).network
        other = sw[i["peer"]]["uplink"]["v4"].split("/")[0] if "peer" in i else r1["default_route"]["v4"]
        peer = i.get("peer", "ISP")
        out.append(f"| R1 {ifn} - {peer} | {n} | R1 {i['v4'].split('/')[0]}, {peer} {other} |")
    out.append(f"| R1 Loopback0 (DHCP server) | {r1['loopback']['v4']} | {r1['loopback']['v6']} |")
    out += ["", "## Switch management (VLAN 99)", "", "| Device | Address |", "| --- | --- |"]
    for d in net.dist():
        mg = net.vlans[99]
        out.append(f"| {d} | {mg.host(a['d1_host'] if d == net.dist()[0] else a['d2_host'])} (SVI) |")
    for d in net.access():
        out.append(f"| {d} | {sw[d]['mgmt']} |")
    w = net.raw.get("wlc")
    if w:
        out.append(f"| {w['name']} | {w['mgmt']} |")
    for r in net.raw.get("dhcp_reservations", []):
        out.append(f"| {r['name']} (DHCP reservation) | {r['ip']} |")
    return "\n".join(out) + "\n"
